function getFormatFrameDimensions(id, dimensions) {
	const src = `${id} ${dimensions || ""}`.toLowerCase();
	if (src.includes("9:16") || src.includes("story") || src.includes("vertical")) return {
		w: 16,
		h: 26
	};
	if (src.includes("4:5") || src.includes("portrait") || src.includes("a4")) return {
		w: 18,
		h: 24
	};
	if (src.includes("16:9") || src.includes("landscape") || src.includes("youtube")) return {
		w: 28,
		h: 17
	};
	if (src.includes("4:3")) return {
		w: 24,
		h: 19
	};
	return {
		w: 21,
		h: 21
	};
}
