function getDims(mode) {
	switch (mode) {
		case "16:9": return {
			w: 1280,
			h: 720
		};
		case "1:1": return {
			w: 960,
			h: 960
		};
		case "4:5": return {
			w: 864,
			h: 1080
		};
		default: return {
			w: 720,
			h: 1280
		};
	}
}
function getCssFilter(f) {
	switch (f) {
		case "warm": return "sepia(0.28) saturate(1.25) contrast(1.04)";
		case "bw": return "grayscale(1) contrast(1.12)";
		case "sepia": return "sepia(0.85)";
		case "bright": return "brightness(1.18) saturate(1.08)";
		case "contrast": return "contrast(1.32) saturate(1.1)";
		default: return "none";
	}
}
function drawVectorShape(ctx, shape, cx, cy, size, color, opacity = 1) {
	ctx.save();
	ctx.globalAlpha = opacity;
	ctx.fillStyle = color;
	const r = size / 2;
	if (shape === "rect") ctx.fillRect(cx - r, cy - r, size, size);
	else if (shape === "circle") {
		ctx.beginPath();
		ctx.arc(cx, cy, r, 0, Math.PI * 2);
		ctx.fill();
	} else if (shape === "cross") {
		const thick = size * .24;
		ctx.fillRect(cx - thick / 2, cy - r, thick, size);
		ctx.fillRect(cx - r * .72, cy - r * .35, r * 1.44, thick);
	} else if (shape === "star") {
		ctx.beginPath();
		for (let i = 0; i < 10; i++) {
			const rad = i % 2 === 0 ? r : r * .44;
			const angle = Math.PI / 5 * i - Math.PI / 2;
			const x = cx + Math.cos(angle) * rad;
			const y = cy + Math.sin(angle) * rad;
			if (i === 0) ctx.moveTo(x, y);
			else ctx.lineTo(x, y);
		}
		ctx.closePath();
		ctx.fill();
	} else if (shape === "heart") {
		ctx.beginPath();
		const topCurve = r * .3;
		ctx.moveTo(cx, cy + r * .85);
		ctx.bezierCurveTo(cx - r * 1.2, cy + r * .1, cx - r * .9, cy - r * .9, cx, cy - topCurve);
		ctx.bezierCurveTo(cx + r * .9, cy - r * .9, cx + r * 1.2, cy + r * .1, cx, cy + r * .85);
		ctx.fill();
	}
	ctx.restore();
}
function wrapLines(ctx, text, maxWidth) {
	const paragraphs = text.split("\n");
	const lines = [];
	for (const para of paragraphs) {
		const words = para.split(" ");
		let current = "";
		for (const w of words) {
			const test = current ? `${current} ${w}` : w;
			if (ctx.measureText(test).width > maxWidth && current) {
				lines.push(current);
				current = w;
			} else current = test;
		}
		lines.push(current);
	}
	return lines;
}
