function extractCleanTextFromWikisourceHtml(html) {
	const doc = new DOMParser().parseFromString(html, "text/html");
	const subPages = [];
	doc.querySelectorAll("a[href^=\"/wiki/\"]").forEach((a) => {
		const href = a.getAttribute("href") || "";
		if (!href.includes(":") && !href.includes("#") && (href.includes("/Chapitre") || href.includes("/Livre") || href.includes("/Chapter") || href.includes("/Part"))) {
			const pageName = decodeURIComponent(href.replace(/^\/wiki\//, ""));
			if (!subPages.includes(pageName)) subPages.push(pageName);
		}
	});
	doc.querySelectorAll("#headertemplate, .ws-noexport, .mw-editsection, .prp-page-qualityheader, .footertemplate, style, script").forEach((el) => el.remove());
	const blocks = [];
	doc.querySelectorAll("h1, h2, h3, h4, p, li, blockquote").forEach((el) => {
		const txt = (el.textContent || "").replace(/\s+/g, " ").trim();
		if (txt && txt.length > 1) blocks.push(txt);
	});
	return {
		text: blocks.length > 0 ? blocks.join("\n\n") : (doc.body.textContent || "").replace(/\n{3,}/g, "\n\n").trim(),
		subPages
	};
}
async function fetchWikisourceBookText(wikiLang, pageTitle, onProgress) {
	const endpoint = `https://${wikiLang}.wikisource.org/w/api.php`;
	const fetchPage = async (title) => {
		const res = await fetchWithTimeout(`${endpoint}?action=parse&page=${encodeURIComponent(title)}&prop=text&format=json&origin=*`, {}, 7500);
		if (!res.ok) throw new Error(`HTTP ${res.status}`);
		const data = await res.json();
		if (data.error || !data.parse?.text?.["*"]) throw new Error(data.error?.info || "Page introuvable sur Wikisource.");
		return extractCleanTextFromWikisourceHtml(data.parse.text["*"]);
	};
	onProgress?.("Téléchargement depuis Wikisource...");
	const root = await fetchPage(pageTitle);
	const prefix = pageTitle.split("/")[0];
	const relevantSubs = root.subPages.filter((sp) => sp.startsWith(prefix) && sp !== pageTitle).slice(0, 12);
	if (root.text.length < 1800 && relevantSubs.length > 0) {
		const sections = [root.text];
		const BATCH_SIZE = 4;
		for (let i = 0; i < relevantSubs.length; i += BATCH_SIZE) {
			const batch = relevantSubs.slice(i, i + BATCH_SIZE);
			onProgress?.(`Téléchargement chapitres ${Math.min(i + batch.length, relevantSubs.length)}/${relevantSubs.length}...`);
			const settled = await Promise.allSettled(batch.map(async (subTitle) => {
				return {
					subTitle,
					text: (await fetchPage(subTitle)).text
				};
			}));
			for (const item of settled) if (item.status === "fulfilled" && item.value.text.trim()) sections.push(`\n==============================\n${item.value.subTitle.replace(/_/g, " ")}\n==============================\n\n${item.value.text}`);
		}
		return sections.join("\n\n");
	}
	return root.text;
}
